public class Phoneme_toString_TriageGen0Test {

    @Test
    public void testToStringWithSinglePhoneme() {
        CharSequence text = "abc";
        LanguageSet languages = LanguageSet.EMPTY; // Assuming EMPTY exists or using a mock-like approach via constructor
        // Since LanguageSet is likely an enum or specific inner class, 
        // we use the constructor provided in the prompt.

        Phoneme phoneme = new Phoneme(text, languages);
        String expected = "abc" + "[" + languages.toString() + "]";
        assertEquals(expected, phoneme.toString());
    }

    @Test
    public void testToStringWithJoinedPhonemes() {
        LanguageSet languages = LanguageSet.EMPTY;
        Phoneme p1 = new Phoneme("a", languages);
        Phoneme p2 = new Phoneme("b", languages);

        // Use the constructor: public Phoneme(final Phoneme phonemeLeft, final Phoneme phonemeRight)
        // The toString implementation uses phonemeText.toString(). 
        // In most implementations of this type, joining phonemes concatenates their texts.
        Phoneme joined = p1.join(p2);

        String expected = "ab" + "[" + languages.toString() + "]";
        assertEquals(expected, joined.toString());
    }

    @Test
    public void testToStringWithComplexLanguageSet() {
        // Using a non-empty language set if possible to ensure coverage of different string representations
        // Assuming LanguageSet has a way to represent multiple languages
        LanguageSet languages = LanguageSet.EMPTY; 
        Phoneme phoneme = new Phoneme("test", languages);

        String result = phoneme.toString();

        // Basic structure validation
        assert result.contains("test");
        assert result.contains("[");
        assert result.endsWith("]");
    }

    @Test
    public void testToStringWithEmptyText() {
        LanguageSet languages = LanguageSet.EMPTY;
        Phoneme phoneme = new Phoneme("", languages);

        String expected = "[" + languages.toString() + "]";
        assertEquals(expected, phoneme.toString());
    }
}
